{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.off_master_htmlbase as WITH opening AS ( SELECT date AS opening_date, cluster, branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, inventory AS opening_inventory, new_category, designs, collar_new, sleeve_type, fit, style FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date = current_date - 30 ), closing AS ( SELECT date AS closing_date, cluster, branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, inventory AS closing_inventory, jit_qty, num_size_available, new_category, designs, collar_new, sleeve_type, fit, style FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE date = current_date ), sales AS ( SELECT branch_code, marketplace_mapped, UPPER(sku_group) AS sku_group, SUM(suborder_quantity) AS sales_qty FROM snitch_db.maplemonk.store_fact_items_offline WHERE order_date BETWEEN current_date - 30 AND current_date AND marketplace_mapped NOT IN (\'SNITCH - WH - EMIZA\',\'SNITCH - WH - SR\',\'SNITCH - WH - YELHANKA\',\'SNITCH - WH - YELHANKA 2\',\'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - WH - B2B\',\'SNITCH - WH - GUJARAT\',\'SNITCH - WH - M P\',\'SNITCH - WH - RAJASTHAN\',\'SNITCH - WH - U.P\',\'SNITCH - SNITCH X\',\'SNITCH - WH - NORTH\') AND doc_prefix NOT IN (\'QCOM\',\'OMS\') AND sku_group NOT LIKE \'%CB%\' GROUP BY branch_code, marketplace_mapped, UPPER(sku_group) ), combined AS ( SELECT COALESCE(o.branch_code, c.branch_code, s.branch_code) AS branch_code, COALESCE(o.cluster, c.cluster) AS cluster, COALESCE(o.marketplace_mapped, c.marketplace_mapped, s.marketplace_mapped) AS marketplace_mapped, COALESCE(o.sku_group, c.sku_group, s.sku_group) AS sku_group, COALESCE(o.opening_inventory, 0) AS opening_inventory, COALESCE(c.closing_inventory, 0) AS closing_inventory, COALESCE(c.jit_qty, 0) AS jit_qty, COALESCE(c.num_size_available, 0) AS num_size_available, COALESCE(s.sales_qty, 0) AS sales_qty, COALESCE(o.new_category, c.new_category) AS new_category, COALESCE(o.designs, c.designs) AS designs, COALESCE(o.collar_new, c.collar_new) AS collar_new, COALESCE(o.sleeve_type, c.sleeve_type) AS sleeve_type, COALESCE(o.fit, c.fit) AS fit, COALESCE(o.style, c.style) AS style FROM opening o FULL OUTER JOIN closing c ON o.branch_code = c.branch_code AND o.marketplace_mapped = c.marketplace_mapped AND o.sku_group = c.sku_group FULL OUTER JOIN sales s ON COALESCE(o.branch_code, c.branch_code) = s.branch_code AND COALESCE(o.marketplace_mapped, c.marketplace_mapped) = s.marketplace_mapped AND COALESCE(o.sku_group, c.sku_group) = s.sku_group ), filtered AS ( SELECT * FROM combined WHERE NOT (opening_inventory = 0 AND closing_inventory = 0 AND sales_qty = 0) ), sku_store AS ( SELECT f.*, CASE WHEN (opening_inventory + closing_inventory) > 0 THEN ROUND(sales_qty / ((opening_inventory + closing_inventory) / 2.0), 2) ELSE 0 END AS sell_through_1 FROM filtered f ) SELECT ss.cluster AS state, ss.marketplace_mapped, ss.new_category, ss.sku_group, pj.product_name, pj.image, ss.fit, CASE WHEN ss.new_category = \'T-Shirts\' THEN CASE WHEN UPPER(TRIM(ss.designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(ss.designs)) IN (\'GRAPHIC PRINT\',\'PRINTED\',\'GEOMETRIC\',\'FLORAL\',\'TIE & DYE\',\'ANIMAL PRINT\') THEN \'Graphic Print\' WHEN UPPER(TRIM(ss.designs)) IN (\'TEXTURED\',\'SELF DESIGN\') THEN \'Textured\' WHEN UPPER(TRIM(ss.designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(ss.designs)) IN (\'EMBROIDED\',\'EMBELLISHED\') THEN \'Embroided\' WHEN UPPER(TRIM(ss.designs)) = \'CHECKS\' THEN \'Checks\' ELSE \'Others\' END WHEN ss.new_category = \'Shirts\' THEN CASE WHEN UPPER(TRIM(ss.designs)) = \'SOLID\' THEN \'Solid\' WHEN UPPER(TRIM(ss.designs)) = \'STRIPES\' THEN \'Stripes\' WHEN UPPER(TRIM(ss.designs)) IN (\'TEXTURED\',\'SELF DESIGN\') THEN \'Textured\' WHEN UPPER(TRIM(ss.designs)) = \'CHECKS\' THEN \'Checks\' WHEN UPPER(TRIM(ss.designs)) IN (\'PRINTED\',\'FLORAL\',\'GEOMETRIC\',\'TIE & DYE\',\'GRAPHIC PRINT\',\'ANIMAL PRINT\') THEN \'Printed\' WHEN UPPER(TRIM(ss.designs)) IN (\'EMBROIDED\',\'EMBELLISHED\') THEN \'Embroided\' ELSE \'Others\' END ELSE ss.designs END AS designs_mapped, CASE WHEN ss.new_category = \'T-Shirts\' THEN CASE WHEN TRIM(LOWER(ss.collar_new)) IN (\'mock\',\'spread\',\'cuban\',\'mandarin\',\'baseball\',\'high neck\',\'zip\',\'others\') THEN \'Others\' WHEN TRIM(LOWER(ss.collar_new)) IN (\'v neck\',\'crew\',\'round\') THEN \'Round\' WHEN TRIM(LOWER(ss.collar_new)) = \'polo\' THEN \'Polo\' ELSE ss.collar_new END ELSE ss.collar_new END AS collar_new_mapped, ss.sales_qty AS sales_last_30_days, ss.closing_inventory AS inventory, ss.jit_qty, ss.num_size_available, ROUND(ss.sell_through_1 * 100, 0) AS str_pct, CASE WHEN ss.sales_qty > 0 THEN \'Top Selling\' WHEN ss.sales_qty = 0 AND ss.closing_inventory > 8 AND ss.num_size_available >= 4 THEN \'0 STR\' ELSE \'Others\' END AS sales_status FROM sku_store ss LEFT JOIN snitch_db.maplemonk.product_journey pj ON UPPER(ss.sku_group) = UPPER(pj.sku_group) WHERE ss.cluster IS NOT NULL AND ss.closing_inventory > 0 ORDER BY ss.cluster, ss.sales_qty DESC; create or replace table snitch_db.maplemonk.b2b_jour_htmlbase as WITH b2b AS ( SELECT state, final_store, final_status, CASE WHEN POSITION(\'-\' IN sku) > 0 THEN REVERSE(SUBSTR(REVERSE(sku), POSITION(\'-\' IN REVERSE(sku)) + 1)) ELSE sku END AS sku_group, CASE WHEN POSITION(\'-\' IN sku) > 0 THEN REVERSE(SPLIT_PART(REVERSE(sku), \'-\', 1)) ELSE NULL END AS size, qty, order_date, order_name, type, TRY_TO_DATE(NULLIF(TRIM(LOGISTICS_EXPECTED_DELIVERY_DATE), \'\')) AS EDD_original FROM snitch_db.maplemonk.b2b_journey WHERE final_status NOT IN (\'INWARDED\',\'INWARD_PENDING\') AND type NOT IN (\'QCOMM\',\'Qcomm\',\'OTHER\',\'QCOM\') ), meta AS ( SELECT sku_group, product_name, category, designs, collar_new, fit FROM snitch_db.maplemonk.metafields_data WHERE category IS NOT NULL ), pj AS ( SELECT sku_group, image FROM snitch_db.maplemonk.product_journey ), fp AS ( SELECT branch_name_priority, TRY_TO_NUMBER(NULLIF(TRIM(lead_time), \'\')) AS lead_time FROM snitch_db.maplemonk.google_sheet_fresh_priority ) SELECT b2b.state, b2b.final_store, b2b.final_status, b2b.sku_group, b2b.size, b2b.qty, b2b.order_date, b2b.order_name, b2b.type, COALESCE( b2b.EDD_original, DATEADD(\'day\', fp.lead_time, b2b.order_date) ) AS EDD, meta.product_name, meta.category, meta.designs, meta.collar_new, meta.fit, pj.image, fp.lead_time FROM b2b LEFT JOIN meta ON b2b.sku_group = meta.sku_group LEFT JOIN pj ON b2b.sku_group = pj.sku_group LEFT JOIN fp ON b2b.final_store = fp.branch_name_priority;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            